type ListNode = { val: number; next: ListNode | null };
function buildList(values: number[], loopTo = -1): ListNode | null {
  const nodes: ListNode[] = values.map((val) => ({ val, next: null }));
  nodes.forEach((n, i) => { n.next = nodes[i + 1] ?? null; });
  if (loopTo >= 0 && nodes.length) nodes[nodes.length - 1].next = nodes[loopTo];
  return nodes[0] ?? null;
}

function loops(head: ListNode | null): boolean {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow!.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}

function hasLoop(values: number[], loopTo: number): boolean {
  return loops(buildList(values, loopTo));
}
